import zeros = require( '@stdlib/ndarray/zeros' );
import columns2tidy = require( './index' );


// TESTS //

// The function returns an array of data sets...
{
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectType DataSet[]
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	columns2tidy( 5, [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( true, [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( false, [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( null, [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( {}, [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( ( x: number ): number => x, [ 'series1', 'series2' ], [ 'index', 'value' ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an array of strings...
{
	columns2tidy( zeros( [ 2, 2 ] ), 5, [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), true, [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), false, [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), null, [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), {}, [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 1, 2 ], [ 'index', 'value' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), ( x: number ): number => x, [ 'index', 'value' ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not an array of strings...
{
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], 5 ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], true ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], false ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], null ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], {} ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], [ 1, 2 ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	columns2tidy(); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ) ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ] ); // $ExpectError
	columns2tidy( zeros( [ 2, 2 ] ), [ 'series1', 'series2' ], [ 'index', 'value' ], {} ); // $ExpectError
}
